    instance->cancel_callback = (XtCallbackProc) NULL;
    instance->help_button = True;
    tmp_txt = CATGETS(Dtb_project_catd, 35, 31, "The children of a paned window must all have the\nsame right-edge and left-edge attachments. The\npanes that were selected to make the paned window\nhad different right-edge attachments. Therefore,\nthe right-edge attachment was changed for one or\nmore of the children, so that they all match. If\nyou don't like the default attachments, you can\nchange them via the Attachments Editor.");
