static int 
dtb_panedwin_ed_name_field_create(
    DtbPanedwinEdDialogInfo instance,
    Widget parent
)
{
    XmString	label_xmstring = NULL;
    Arg	args[23];	/* need 18 args (add 5 to be safe) */
    int	n = 0;
    
    if (instance->name_field_rowcolumn == NULL) {
        instance->name_field_rowcolumn =
            XtVaCreateWidget("name_field_rowcolumn",
                xmRowColumnWidgetClass,
                parent,
                XmNadjustLast, True,
                XmNspacing, 0,
                XmNmarginWidth, 0,
                XmNmarginHeight, 0,
                XmNentryAlignment, XmALIGNMENT_END,
                XmNorientation, XmHORIZONTAL,
                NULL);
    }
    if (instance->name_field_rowcolumn == NULL)
        return -1;

    label_xmstring = XmStringCreateLocalized(CATGETS(Dtb_project_catd, 35, 5, "Object Name:"));
    if (instance->name_field_label == NULL) {
        instance->name_field_label =
            XtVaCreateWidget("name_field_label",
                xmLabelWidgetClass,
                instance->name_field_rowcolumn,
                XmNlabelString, label_xmstring,
                NULL);
        XmStringFree(label_xmstring);
        label_xmstring = NULL;
    }
    if (instance->name_field_label == NULL)
        return -1;

    if (instance->name_field == NULL) {
        n = 0;
        XtSetArg(args[n], XmNmaxLength, 80);  ++n;
        XtSetArg(args[n], XmNeditable, True);  ++n;
        XtSetArg(args[n], XmNcursorPositionVisible, True);  ++n;
        XtSetArg(args[n], XmNcolumns, 30);  ++n;
        instance->name_field =
            XmCreateTextField(instance->name_field_rowcolumn,
                "name_field", args, n);
    }
    if (instance->name_field == NULL)
        return -1;

    return 0;
}



static int 
dtb_panedwin_ed_init_state_cbox_create(
    DtbPanedwinEdDialogInfo instance,
    Widget parent
)
{
    XmString	label_xmstring = NULL;
    Arg	args[13];	/* need 8 args (add 5 to be safe) */
    int	n = 0;
    Widget	init_state_cbox_choice_items[2];
    
    if (instance->init_state_cbox_rowcolumn == NULL) {
        instance->init_state_cbox_rowcolumn =
            XtVaCreateWidget("init_state_cbox_rowcolumn",
                xmRowColumnWidgetClass,
                parent,
                XmNpacking, XmPACK_TIGHT,
                XmNisHomogeneous, False,
                XmNadjustLast, True,
                XmNspacing, 0,
                XmNmarginWidth, 0,
                XmNmarginHeight, 0,
                XmNentryAlignment, XmALIGNMENT_END,
                XmNorientation, XmHORIZONTAL,
                NULL);
    }
    if (instance->init_state_cbox_rowcolumn == NULL)
        return -1;

    label_xmstring = XmStringCreateLocalized(CATGETS(Dtb_project_catd, 35, 24, "Initial State:"));
    if (instance->init_state_cbox_label == NULL) {
        instance->init_state_cbox_label =
            XtVaCreateWidget("init_state_cbox_label",
                xmLabelWidgetClass,
                instance->init_state_cbox_rowcolumn,
                XmNlabelString, label_xmstring,
                NULL);
        XmStringFree(label_xmstring);
        label_xmstring = NULL;
    }
    if (instance->init_state_cbox_label == NULL)
        return -1;

    if (instance->init_state_cbox == NULL) {
        n = 0;
        XtSetArg(args[n], XmNradioBehavior, False);  ++n;
        XtSetArg(args[n], XmNentryClass, xmToggleButtonWidgetClass);  ++n;
        XtSetArg(args[n], XmNnumColumns, 1);  ++n;
        XtSetArg(args[n], XmNisHomogeneous, True);  ++n;
        XtSetArg(args[n], XmNspacing, 0);  ++n;
        XtSetArg(args[n], XmNrowColumnType, XmWORK_AREA);  ++n;
        XtSetArg(args[n], XmNpacking, XmPACK_TIGHT);  ++n;
        XtSetArg(args[n], XmNorientation, XmHORIZONTAL);  ++n;
        instance->init_state_cbox =
            XmCreateRadioBox(instance->init_state_cbox_rowcolumn,
                "init_state_cbox", args, n);
    }
    if (instance->init_state_cbox == NULL)
        return -1;

    label_xmstring = XmStringCreateLocalized(CATGETS(Dtb_project_catd, 35, 25, "Visible"));
    if (instance->init_state_cbox_items.Visible_item == NULL) {
        instance->init_state_cbox_items.Visible_item =
            XtVaCreateManagedWidget("Visible_item",
                xmToggleButtonWidgetClass,
                instance->init_state_cbox,
                XmNset, True,
                XmNlabelString, label_xmstring,
                NULL);
        XmStringFree(label_xmstring);
        label_xmstring = NULL;
    }
    if (instance->init_state_cbox_items.Visible_item == NULL)
        return -1;

    label_xmstring = XmStringCreateLocalized(CATGETS(Dtb_project_catd, 35, 26, "Active"));
    if (instance->init_state_cbox_items.Active_item == NULL) {
        instance->init_state_cbox_items.Active_item =
            XtVaCreateManagedWidget("Active_item",
                xmToggleButtonWidgetClass,
                instance->init_state_cbox,
                XmNset, True,
                XmNlabelString, label_xmstring,
                NULL);
        XmStringFree(label_xmstring);
        label_xmstring = NULL;
    }
    if (instance->init_state_cbox_items.Active_item == NULL)
        return -1;

    return 0;
}



